function [Ts1, Ts2, Ts3, T1, T2, T3, T4, T5] = f_ani_ortho_time_coeffs(n, m, lam, Ro, Ca, ani1, ani2, epnmeq, epnm)

    Ts1 = (5.*(3.*ani1+ani2)+12.*(ani1+ani2).*lam^3-40.*ani1.*lam^4+20.*(2.*ani1+ani2).*lam^6-80.*ani1.*lam^7+(113.*ani1-17.*ani2).*lam^8-20.*(3.*ani1+ani2).*lam^9)/(80.*lam^8);
    Ts2 = (ani2.*lam^3.*(2+5.*lam^3-7.*lam^5)+5.*ani1.*(1-2.*lam^4+lam^7.*(4+lam.*(-7+4.*lam))))/(20.*lam^8);
    Ts3 = -(((ani1-ani2).*(-5+12.*lam^3+40.*lam^6-67.*lam^8+20.*lam^9))/(80.*lam^8));

    T1 = zeros(length(n)+1,1); T2 = T1; T3 = T1; T4 = T1; T5 = T1;

for i = 1:length(n)
    T1(i+1) = 1/(4.*Ca.*lam^13.*(3+n(i)).*(8+n(i)).*Ro^5).*(lam.*Ro)^-n(i).*(-((3+n(i)).*...
        (8+n(i)).*Ro^3.*(2.*epnmeq(i).*lam^(4+n(i)).*(4.*(ani1-ani2).*lam^2.*m(i)^2-8.*ani1.*...
        lam^3.*(1+n(i))+(ani1-ani2).*lam^5.*(1+n(i))-4.*ani1.*n(i).*(1+n(i))).*Ro^n(i)+4.*(3.*...
        ani1+ani2).*epnmeq(i).*(1+n(i)).*(2.*lam^3+n(i)).*(lam.*Ro)^n(i)+epnm(i).*lam^3.*...
        (lam^(3+n(i)).*(-((45.*ani1+17.*ani2).*(1+n(i)))+28.*ani1.*lam^4.*(1+n(i))-(3.*ani1-5.*ani2).*...
        lam^6.*(1+n(i))-4.*ani1.*lam^7.*(1+n(i))+(3.*ani1+ani2).*lam^9.*(1+n(i))+(ani1-ani2).*lam^3.*...
        (1-8.*m(i)^2+n(i))+8.*ani1.*lam.*(-1+n(i)^2)).*Ro^n(i)-2.*(3.*ani1+ani2).*(1+n(i)).*(-3+2.*n(i)).*...
        (lam.*Ro)^n(i))))+lam^2.*(lam*Ro)^n(i).*(-epnm(i).*(lam*Ro)^3+epnmeq(i).*Ro^3).*(-(((3.*ani1+ani2).*lam^12.*...
        (1+n(i)).*(5+n(i)).*(8+n(i))-3.*(3.*ani1+ani2).*n(i).*(1+n(i)).*(5+n(i)).*(8+n(i))-3.*lam^3.*...
        (1+n(i)).*(5+n(i)).*(-ani2.*(-16+n(i))+3.*ani1.*(16+n(i)))+2.*lam^6.*(2.*ani2.*m(i)^2.*(8+n(i)).*...
        (13+5.*n(i))-2.*ani1.*m(i)^2.*(8+n(i)).*(17+7.*n(i))+3.*ani1.*(1+n(i)).*(2+n(i)).*(10+n(i).*(8+n(i)))+...
        ani2.*(1+n(i)).*(2+n(i)).*(30+n(i).*(8+n(i))))+lam^9.*(5+n(i)).*(8+n(i)).*(ani2.*((1+n(i)).*(2+n(i))^2-4.*...
        m(i)^2.*(5+n(i)))+ani1.*(2+14.*n(i)+(5+n(i)).*(-4.*m(i)^2+3.*n(i)^2)))).*hyp2f1(-(2/3),(3+n(i))/3,(6+n(i))/3,1-1/lam^3))-...
        4.*ani1.*lam^3.*(1+n(i)).*(8+n(i)).*(-lam^6.*(4+n(i))+n(i).*(4+n(i))+lam^3.*(8+n(i))).*hyp2f1(-(1/3),(3+n(i))/3,(6+n(i))/3,1-1/lam^3)+...
        (2.*(3.*ani1+ani2).*lam^12.*(1+n(i)).*(8+n(i))-6.*(3.*ani1+ani2).*n(i).*(1+n(i)).*(8+n(i))-6.*lam^3.*(1+n(i)).*...
        (-ani2.*(-16+n(i))+3.*ani1.*(16+n(i)))+lam^6.*(8+n(i)).*(ani2.*(1+n(i))^2.*(2+n(i)).*(3+n(i))+ani1.*(1+n(i)).*(3+...
        n(i)).*(2+3.*n(i).*(3+n(i)))-4.*ani2.*m(i)^2.*(8+n(i).*(7+n(i)))-4.*ani1.*m(i)^2.*(14+n(i).*(7+n(i))))+2.*lam^9.*(8+...
        n(i)).*(ani2.*((1+n(i)).*(2+n(i))^2-4.*m(i)^2.*(5+n(i)))+ani1.*(2+14.*n(i)+(5+n(i)).*(-4.*m(i)^2+3.*n(i)^2)))).*...
        hyp2f1(1/3,(3+n(i))/3,(6+n(i))/3,1-1/lam^3)+4.*ani1.*lam^3.*(8+n(i)).*(-lam^6.*(1+n(i))+n(i).*(1+n(i))+lam^3.*(2+...
        4.*n(i)+(3+n(i)).*(-2.*m(i)^2+n(i)^2))).*hyp2f1(2/3,(3+n(i))/3,(6+n(i))/3,1-1/lam^3)));

    T2(i+1) = 1/(2.*Ca.*Ro^2).*((4.*(ani1-ani2).*epnm(i).*m(i)^2)/lam^4-2.*ani1.*epnm(i).*(1+n(i))-(10.*...
        ani1.*epnm(i).*(1+n(i)))/lam^3-((2.*ani1+ani2).*epnm(i).*(1+n(i)))/lam+2.*ani1.*epnm(i).*lam^2.*...
        (1+n(i))-(8.*ani1.*epnmeq(i).*n(i).*(1+n(i)))/lam^13+(4.*ani1.*epnmeq(i).*n(i).*(1+n(i)))/lam^9+(4.*...
        ani1.*(1+n(i)).*(epnm(i)+2.*epnmeq(i)-epnm(i).*n(i)))/lam^6+(4.*(-ani1+ani2).*epnmeq(i).*m(i)^2+(28.*...
        ani1+ani2).*epnm(i).*(1+n(i)))/lam^7+(4.*ani1.*(1+n(i)).*(-4.*epnmeq(i)+epnm(i).*(-3+2.*n(i))))/lam^10+...
        1/(lam^11.*(3+n(i)).*(8+n(i))).*(epnmeq(i)-epnm(i).*lam^3).*((2.*ani1.*lam^12.*(1+n(i)).*(5+n(i)).*(8+n(i))+...
