        2.*ani1.*lam^3.*(1+n(i)).*(8+n(i)).*(lam^6.*(4+n(i))+n(i).*(4+n(i))+lam^3.*(8+3.*n(i))).*hyp2f1(-(1/3),(3+n(i))/3,(6+n(i))/3,1-1/lam^3)+...
        2.*(-2.*ani1.*lam^12.*(1+n(i)).*(8+n(i))-6.*ani1.*n(i).*(1+n(i)).*(8+n(i))-3.*lam^3.*(1+n(i)).*(-ani2.*n(i)+4.*ani1.*...
        (8+n(i)))+lam^9.*(8+n(i)).*(2.*(ani1-ani2).*m(i)^2.*(5+n(i))+(1+n(i)).*(ani2-2.*ani1.*n(i).*(4+n(i))))+lam^6.*(8+n(i)).*...
        ((ani1-ani2).*m(i)^2.*(2+n(i)).*(5+n(i))+(1+n(i)).*(ani2+n(i).*(ani2-ani1.*(3+n(i))^2)))).*hyp2f1(1/3,(3+n(i))/3,(6+n(i))/3,1-1/lam^3)-...
        2.*ani1.*lam^3.*(1+n(i)).*(8+n(i)).*(-lam^6-n(i)+lam^3.*(-2+n(i).*(2+n(i)))).*hyp2f1(2/3,(3+n(i))/3,(6+n(i))/3,1-1/lam^3)));

    T3(i+1) = 1/(4.*Ca.*(3+n(i)).*(8+n(i))).*(ani1-ani2).*lam^(-13-n(i)).*(1+n(i)).*Ro^(-2-n(i)).*(lam^n(i).*(3+n(i)).*(8+n(i)).*(2.*...
        epnmeq(i).*(-4.*lam^3+lam^9-2.*n(i))+epnm(i).*lam^3.*(-6+11.*lam^3+lam^6+lam^9-lam^12+4.*n(i))).*Ro^n(i)-lam^2.*(epnmeq(i)-...
        epnm(i).*lam^3).*(lam^12.*(5+n(i)).*(8+n(i))-3.*n(i).*(5+n(i)).*(8+n(i))-3.*lam^3.*(5+n(i)).*(16+5.*n(i))+lam^9.*(5+n(i)).*...
        (8+n(i)).*(-2+n(i).*(4+n(i)))-6.*lam^6.*(2+n(i)).*(10+n(i).*(8+n(i)))).*(lam.*Ro)^n(i).*hyp2f1(-(2/3),(3+n(i))/3,(6+n(i))/3,1-1/lam^3)+...
        lam^2.*(epnmeq(i)-epnm(i).*lam^3).*(2.*lam^12.*(8+n(i))-6.*n(i).*(8+n(i))-6.*lam^3.*(16+5.*n(i))+lam^6.*(3+n(i)).*(8+n(i)).*(-2+n(i).*...
        (3+n(i)))+2.*lam^9.*(8+n(i)).*(-2+n(i).*(4+n(i)))).*(lam.*Ro)^n(i).*hyp2f1(1/3,(3+n(i))/3,(6+n(i))/3,1-1/lam^3));

    T4(i+1) = 1/(2.*Ca.*lam^13.*Ro^2).*(epnmeq(i)-epnm(i).*lam^3).*(-2.*ani2.*lam^6+2.*ani1.*(-2+lam^3.*(-5+2.*lam+lam^3-3.*n(i)+2.*lam^4.*(1+...
        n(i))-lam^6.*(1+n(i))))+1/((3+n(i)).*(7+n(i)).*(8+n(i)).*(11+n(i))).*lam^2.*((7+n(i)).*(24.*ani1.*(5+n(i)).*(8+n(i))+lam^9.*(5+n(i)).*...
        (8+n(i)).*(11+n(i)).*(-4.*ani2+ani1.*(-3+5.*n(i)))+2.*lam^3.*(5+n(i)).*(-ani2.*(11+n(i))+ani1.*(327+n(i).*(8+n(i)).*(37+4.*n(i))))+lam^6.*...
        (2.*ani2.*(3+n(i)).*(9+n(i)).*(11+n(i))+ani1.*(-1394+n(i).*(-423+n(i).*(124+13.*n(i)))))).*hyp2f1(-(2/3),(3+n(i))/3,(6+n(i))/3,1-1/lam^3)-...
        4.*ani1.*lam^3.*(8+n(i)).*(11+n(i)).*(2.*(4+n(i))+lam^3.*(36+n(i).*(32+n(i).*(11+n(i))))).*hyp2f1(-(1/3),(3+n(i))/3,(6+n(i))/3,1-1/lam^3)-...
        (7+n(i)).*(48.*ani1.*(8+n(i))+2.*lam^9.*(8+n(i)).*(11+n(i)).*(-4.*ani2+ani1.*(-3+5.*n(i)))+lam^6.*(8+n(i)).*(11+n(i)).*(2.*ani2.*(-5+2.*...
        m(i)^2-2.*n(i))+ani1.*(-4.*(7+m(i)^2)+n(i)+5.*n(i)^2))+4.*lam^3.*(-ani2.*(11+n(i))+ani1.*(327+n(i).*(8+n(i)).*(37+4.*n(i))))).*...
        hyp2f1(1/3,(3+n(i))/3,(6+n(i))/3,1-1/lam^3)-2.*ani1.*lam^3.*(8+n(i)).*(11+n(i)).*(-4+lam^3.*(-3+n(i)).*(7+n(i))).*...
        hyp2f1(2/3,(3+n(i))/3,(6+n(i))/3,1-1/lam^3)));

    T5(i+1) = 1/(4.*Ca.*(3+n(i)).*(8+n(i)).*(11+n(i))).*(ani1-ani2).*lam^(-13-n(i)).*(epnmeq(i)-epnm(i).*lam^3).*Ro^(-2-n(i)).*(2.*lam^n(i).*(3+...
        n(i)).*(8+n(i)).*(11+n(i)).*(-2+3.*lam^6+lam^9.*(1+n(i))-lam^3.*(5+3.*n(i))).*Ro^n(i)+lam^2.*(lam.*Ro)^n(i).*((24.*(5+n(i)).*(8+n(i))-...
        lam^9.*(5+n(i)).*(8+n(i)).*(11+n(i)).*(-3+5.*n(i))+2.*lam^3.*(3+n(i)).*(5+n(i)).*(131+n(i).*(57+4.*n(i)))+lam^6.*(3+n(i)).*(694+...
        n(i).*(437+33.*n(i)))).*hyp2f1(-(2/3),(3+n(i))/3,(6+n(i))/3,1-1/lam^3)+(-48.*(8+n(i))+2.*lam^9.*(8+n(i)).*(11+n(i)).*(-3+5.*n(i))+...
        lam^6.*(8+n(i)).*(11+n(i)).*(-36+n(i)+5.*n(i)^2)-4.*lam^3.*(3+n(i)).*(131+n(i).*(57+4.*n(i)))).*hyp2f1(1/3,(3+n(i))/3,(6+n(i))/3,1-1/lam^3)));
end

